CREATE TABLE bank_tasks (
	id INTEGER NOT NULL, 
	grade SMALLINT NOT NULL, 
	block VARCHAR(32) NOT NULL, 
	bank_type VARCHAR(16) NOT NULL, 
	topic_title VARCHAR(255) NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	statement TEXT NOT NULL, 
	difficulty VARCHAR(32) NOT NULL, 
	answer VARCHAR(128) NOT NULL, 
	solution TEXT NOT NULL, 
	hint TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
INSERT INTO "bank_tasks" VALUES(1,7,'MECHANICS','OPEN','Плотность вещества и масса','Масса дубового бруска','Найдите массу деревянного бруска из сухого дуба объемом 0,004 м³, если плотность дуба равна 700 кг/м³. Ответ выразите в кг.','Базовый','2.8','Дано: V = 0,004 м³, ρ = 700 кг/м³.
Формула: m = ρ * V.
Вычисление: m = 700 * 0,004 = 2,8 кг.
Ответ: 2,8 кг.','Используйте базовую формулу связи массы, объема и плотности: m = ρ * V.','2026-09-24 19:30:15.466972','2026-09-24 19:30:15.466979');
INSERT INTO "bank_tasks" VALUES(2,7,'MECHANICS','OPEN','Скорость, путь и время','Средняя скорость велосипедиста','Велосипедист первые 30 минут двигался со скоростью 12 км/ч, а следующие 10 минут стоял на ремонте, после чего за 20 минут проехал еще 6 км. Найдите среднюю скорость велосипедиста на всем пути в км/ч.','Средний','12','1) Первый участок: t1 = 30 мин = 0,5 ч, s1 = v1 * t1 = 12 * 0,5 = 6 км.
2) Остановка: t2 = 10 мин = 1/6 ч, s2 = 0 км.
3) Третий участок: t3 = 20 мин = 1/3 ч, s3 = 6 км.
Общий путь: S = s1 + s2 + s3 = 6 + 0 + 6 = 12 км.
Общее время: T = 30 + 10 + 20 = 60 мин = 1 час.
Средняя скорость: v_ср = S / T = 12 / 1 = 12 км/ч.
Ответ: 12.','Средняя скорость — это ВЕСЬ пройденный путь, деленный на ВСЕ затраченное время (включая остановки): v_ср = S_общ / T_общ.','2026-09-24 19:30:15.466980','2026-09-24 19:30:15.466981');
INSERT INTO "bank_tasks" VALUES(3,7,'MECHANICS','OPEN','Гидростатическое давление','Давление воды на дно аквариума','Аквариум высотой 50 см наполнен водой до уровня 40 см. Определите гидростатическое давление воды на дно аквариума. Примите g = 10 Н/кг, плотность воды 1000 кг/м³. Ответ дайте в Па.','Базовый','4000','Дано: h = 40 см = 0,4 м (важна именно глубина столба жидкости!), ρ = 1000 кг/м³, g = 10 Н/кг.
Формула давления столба жидкости: p = ρ * g * h.
Вычисление: p = 1000 * 10 * 0,4 = 4000 Па.
Ответ: 4000 Па.','Обратите внимание: в формулу p = ρgh подставляется высота налитой воды (0,4 м), а не полная высота аквариума.','2026-09-24 19:30:15.466982','2026-09-24 19:30:15.466983');
INSERT INTO "bank_tasks" VALUES(4,7,'MECHANICS','OPEN','Сила Архимеда и условия плавания тел','Выталкивающая сила в керосине','Металлическая деталь объемом 250 см³ полностью погружена в керосин (плотность керосина 800 кг/м³). Чему равна архимедова сила, действующая на деталь? Примите g = 10 Н/кг. Ответ дайте в Ньютонах.','Базовый','2','Дано: V = 250 см³ = 250 * 10⁻⁶ м³ = 0,00025 м³, ρ_ж = 800 кг/м³, g = 10 Н/кг.
Формула силы Архимеда: F_A = ρ_ж * g * V_погр.
Вычисление: F_A = 800 * 10 * 0,00025 = 2 Н.
Ответ: 2.','Не забудьте перевести объем из см³ в м³: 1 см³ = 10⁻⁶ м³.','2026-09-24 19:30:15.466984','2026-09-24 19:30:15.466984');
INSERT INTO "bank_tasks" VALUES(5,7,'MECHANICS','OPEN','Простые механизмы: рычаг','Равновесие рычага','К меньшему плечу рычага длиной 10 см подвешен груз силой тяжести 150 Н. Какую силу необходимо приложить к большему плечу длиной 50 см, чтобы удержать рычаг в равновесии? Ответ выразите в Н.','Базовый','30','Правило равновесия рычага (правило моментов): F1 * l1 = F2 * l2.
150 * 0,1 = F2 * 0,5 => 15 = 0,5 * F2 => F2 = 30 Н.
Ответ: 30 Н.','Произведение силы на плечо слева равно произведению силы на плечо справа: F1 * l1 = F2 * l2.','2026-09-24 19:30:15.466985','2026-09-24 19:30:15.466986');
INSERT INTO "bank_tasks" VALUES(6,7,'MECHANICS','CLOSED','Плотность и масса сплавов','Плотность двухкомпонентного сплава','Сплав изготовлен из 300 г меди (плотность 8900 кг/м³) и 200 г цинка (плотность 7100 кг/м³). Считая объем сплава равным сумме объемов компонентов, найдите среднюю плотность сплава. Ответ округлите до десятков (кг/м³).','Средний','8080','1) m_общ = 0,3 + 0,2 = 0,5 кг.
2) V1 = m1 / ρ1 = 0,3 / 8900 ≈ 3,371 * 10⁻⁵ м³.
3) V2 = m2 / ρ2 = 0,2 / 7100 ≈ 2,817 * 10⁻⁵ м³.
4) V_общ = V1 + V2 ≈ 6,188 * 10⁻⁵ м³.
5) ρ_ср = m_общ / V_общ = 0,5 / (6,188 * 10⁻⁵) ≈ 8080 кг/м³.
Критерии оценивания: верный учет объемов (нельзя просто усреднять плотности!), правильный перевод единиц.','Плотность сплава — это общая масса, деленная на суммарный объем компонентов: ρ = (m1 + m2) / (V1 + V2).','2026-09-24 19:30:15.466986','2026-09-24 19:30:15.466987');
INSERT INTO "bank_tasks" VALUES(7,7,'MECHANICS','CLOSED','Закон Архимеда и глубина погружения','Осадка деревянной льдины в пресной воде','Плоская льдина площадью 2 м² и толщиной 30 см плавает в пресной воде (плотность 1000 кг/м³). Плотность льда 900 кг/м³. Какой максимальный груз в кг можно положить на льдину, чтобы она не утонула? g = 10 Н/кг.','Средний','60','1) Объем льдины: V = S * h = 2 * 0,3 = 0,6 м³.
2) Масса льдины: m_льда = ρ_льда * V = 900 * 0,6 = 540 кг.
3) Максимальная архимедова сила при полном погружении льдины: F_A = ρ_в * g * V = 1000 * 10 * 0,6 = 6000 Н.
4) Условие плавания на грани затопления: (m_льда + M_гр) * g = F_A => 540 + M_гр = 600 => M_гр = 60 кг.
Ответ: 60 кг.','Условие полного погружения без утопления: сила Архимеда от объема льдины уравновешивает силу тяжести льда и груза вместе.','2026-09-24 19:30:15.466988','2026-09-24 19:30:15.466988');
INSERT INTO "bank_tasks" VALUES(8,7,'MECHANICS','CLOSED','Простые механизмы и КПД','КПД наклонной плоскости с грузом','Груз массой 45 кг равномерно поднимают по наклонной плоскости длиной 4 м на высоту 1,2 м, прикладывая силу тяги 150 Н, направленную вдоль плоскости. Определите КПД наклонной плоскости в процентах. g = 10 Н/кг.','Средний','90','1) Полезная работа (подъем груза на высоту): A_пол = m * g * h = 45 * 10 * 1,2 = 540 Дж.
2) Затраченная работа (тяга по длине плоскости): A_затр = F * L = 150 * 4 = 600 Дж.
3) КПД = (A_пол / A_затр) * 100% = (540 / 600) * 100% = 90%.
Ответ: 90%.','Полезная работа равна m*g*h, а затраченная — произведению силы тяги на длину наклонной плоскости F*L.','2026-09-24 19:30:15.466989','2026-09-24 19:30:15.466990');
INSERT INTO "bank_tasks" VALUES(9,7,'MECHANICS','CLOSED','Сообщающиеся сосуды и давление разнородных жидкостей','Уровень керосина и воды в U-образной трубке','В U-образную трубку налили воду (плотность 1000 кг/м³), затем в одно из колен долили столб керосина (плотность 800 кг/м³) высотой 20 см. На какую высоту столб воды поднимется над границей раздела жидкостей? Ответ дайте в см.','Средний','16','Давления на уровне границы раздела одинаковы: p_кер = p_воды => ρ_кер * g * h_кер = ρ_воды * g * h_воды.
Отсюда h_воды = (ρ_кер * h_кер) / ρ_воды = (800 * 20) / 1000 = 16 см.
Ответ: 16 см.','В сообщающихся сосудах высоты столбов разнородных жидкостей обратно пропорциональны их плотностям: h1 / h2 = ρ2 / ρ1.','2026-09-24 19:30:15.466990','2026-09-24 19:30:15.466991');
INSERT INTO "bank_tasks" VALUES(10,8,'THERMODYNAMICS','OPEN','Количество теплоты при нагревании','Нагревание медного паяльника','Какое количество теплоты необходимо передать медной детали массой 500 г, чтобы нагреть ее от 20 °C до 420 °C? Удельная теплоемкость меди равна 400 Дж/(кг·°C). Ответ дайте в кДж.','Базовый','80','Дано: m = 500 г = 0,5 кг, c = 400 Дж/(кг·°C), Δt = 420 - 20 = 400 °C.
Формула: Q = c * m * Δt.
Вычисление: Q = 400 * 0,5 * 400 = 80 000 Дж = 80 кДж.
Ответ: 80 кДж.','Формула Q = c * m * (t2 - t1). Не забудьте перевести 500 г в 0,5 кг и ответ выразить в килоджоулях.','2026-09-24 19:30:15.466992','2026-09-24 19:30:15.466992');
INSERT INTO "bank_tasks" VALUES(11,8,'THERMODYNAMICS','OPEN','Фазовые переходы: плавление льда','Энергия для расплавления льда','Сколько теплоты потребуется, чтобы расплавить 2 кг льда, уже находящегося при температуре плавления 0 °C? Удельная теплота плавления льда λ = 3,3 * 10⁵ Дж/кг. Ответ дайте в кДж.','Базовый','660','Дано: m = 2 кг, λ = 3,3 * 10⁵ Дж/кг = 330 000 Дж/кг.
Формула: Q = λ * m.
Вычисление: Q = 330 000 * 2 = 660 000 Дж = 660 кДж.
Ответ: 660.','Поскольку лед уже при температуре 0 °C, энергия требуется только на плавление: Q = λ * m.','2026-09-24 19:30:15.466993','2026-09-24 19:30:15.466994');
INSERT INTO "bank_tasks" VALUES(12,8,'THERMODYNAMICS','OPEN','Сгорание топлива и КПД','Расход керосина при нагревании воды','В примусе сожгли 40 г керосина (удельная теплота сгорания 46 МДж/кг). Какое количество теплоты выделилось при полном сгорании топлива? Ответ выразите в кДж.','Базовый','1840','Дано: m = 40 г = 0,04 кг, q = 46 МДж/кг = 46 * 10⁶ Дж/кг.
Формула: Q = q * m.
Вычисление: Q = 46 * 10⁶ * 0,04 = 1 840 000 Дж = 1840 кДж.
Ответ: 1840 кДж.','Формула сгорания топлива: Q = q * m.','2026-09-24 19:30:15.466994','2026-09-24 19:30:15.466995');
INSERT INTO "bank_tasks" VALUES(13,8,'THERMODYNAMICS','CLOSED','Уравнение теплового баланса','Установление температуры в калориметре','В калориметр, содержащий 300 г воды при температуре 15 °C, опустили латунный цилиндр массой 200 г, нагретый до 100 °C. Пренебрегая потерями тепла и теплоемкостью калориметра, определите установившуюся температуру смеси. с_воды = 4200 Дж/(кг·°C), с_латуни = 380 Дж/(кг·°C). Ответ округлите до десятых (°C).','Средний','19.9','Уравнение теплового баланса: Q_отд = Q_получ.
m_л * c_л * (t_нач_л - θ) = m_в * c_в * (θ - t_нач_в).
0,2 * 380 * (100 - θ) = 0,3 * 4200 * (θ - 15)
76 * (100 - θ) = 1260 * (θ - 15)
7600 - 76θ = 1260θ - 18900
1336θ = 26500 => θ ≈ 19,835 ≈ 19,9 °C.
Ответ: 19,9 °C.','Теплота, отданная остывающей латунью, равна теплоте, полученной нагревающейся водой.','2026-09-24 19:30:15.466996','2026-09-24 19:30:15.466996');
INSERT INTO "bank_tasks" VALUES(14,8,'THERMODYNAMICS','CLOSED','Тепловой баланс с фазовым переходом','Таяние льда в горячей воде','В сосуд с 1,5 кг воды при температуре 40 °C бросают лед при температуре 0 °C. Какую массу льда нужно добавить, чтобы вся вода охладилась до 0 °C, а лед полностью растаял? c_в = 4200 Дж/(кг·°C), λ_льда = 3,3 * 10⁵ Дж/кг. Ответ дайте в граммах с округлением до целых.','Повышенный (ОГЭ №23-25)','764','1) Тепло, отдаваемое водой при остывании от 40 °C до 0 °C:
Q_отд = c_в * m_в * (40 - 0) = 4200 * 1,5 * 40 = 252 000 Дж.
2) Это тепло идет на плавление льда массы m_л:
Q_получ = λ * m_л = 330 000 * m_л.
3) Уравнение баланса: 330 000 * m_л = 252 000 => m_л = 252 / 330 ≈ 0,7636 кг ≈ 764 г.
Ответ: 764 г.','Вода отдает тепло при остывании до 0 °C, а лед поглощает его при плавлении без изменения температуры.','2026-09-24 19:30:15.466997','2026-09-24 19:30:15.466998');
INSERT INTO "bank_tasks" VALUES(15,8,'ELECTRODYNAMICS','OPEN','Закон Ома для участка цепи','Сила тока в нагревательном элементе','Электрический нагреватель сопротивлением 44 Ом включен в сеть напряжением 220 В. Определите силу тока в нагревателе. Ответ выразите в Амперах.','Базовый','5','Закон Ома для участка цепи: I = U / R.
I = 220 / 44 = 5 А.
Ответ: 5 А.','Используйте закон Ома: I = U / R.','2026-09-24 19:30:15.466998','2026-09-24 19:30:15.466999');
INSERT INTO "bank_tasks" VALUES(16,8,'ELECTRODYNAMICS','OPEN','Параллельное соединение проводников','Общее сопротивление параллельной цепи','Два резистора сопротивлением R1 = 6 Ом и R2 = 12 Ом соединены параллельно. Чему равно эквивалентное сопротивление этого участка цепи? Ответ дайте в Омах.','Базовый','4','Формула параллельного соединения двух резисторов: R_экв = (R1 * R2) / (R1 + R2).
R_экв = (6 * 12) / (6 + 12) = 72 / 18 = 4 Ом.
Ответ: 4 Ом.','Для двух параллельных проводников: R = (R1 * R2) / (R1 + R2).','2026-09-24 19:30:15.467000','2026-09-24 19:30:15.467000');
INSERT INTO "bank_tasks" VALUES(17,8,'ELECTRODYNAMICS','OPEN','Геометрическая оптика: плоское зеркало','Расстояние до изображения в зеркале','Человек стоял на расстоянии 1,5 м от плоского вертикального зеркала, а затем отошел от него еще на 50 см назад. Каково теперь расстояние между человеком и его изображением в зеркале? Ответ дайте в метрах.','Базовый','4','1) Новое расстояние от человека до зеркала: d = 1,5 + 0,5 = 2,0 м.
2) В плоском зеркале изображение мнимое и находится на таком же расстоянии за зеркалом: f = d = 2,0 м.
3) Расстояние между предметом и его изображением: L = d + f = 2,0 + 2,0 = 4 м.
Ответ: 4 м.','Изображение в плоском зеркале находится на точно таком же расстоянии за зеркалом, на каком предмет находится перед ним.','2026-09-24 19:30:15.467001','2026-09-24 19:30:15.467001');
INSERT INTO "bank_tasks" VALUES(18,8,'ELECTRODYNAMICS','CLOSED','Закон Джоуля-Ленца и КПД чайника','Время закипания воды в электрочайнике','Электрочайник мощностью 1000 Вт с КПД 84% нагревает 1 литр воды от 20 °C до кипения при 100 °C. За сколько секунд закипит вода? c_воды = 4200 Дж/(кг·°C), плотность воды 1000 кг/м³. Ответ выразите в секундах.','Средний','400','1) Масса воды: m = ρ * V = 1 кг.
2) Полезная теплота для нагрева: Q_пол = c * m * Δt = 4200 * 1 * 80 = 336 000 Дж.
3) Полная затраченная электрическая энергия: A_затр = Q_пол / η = 336 000 / 0,84 = 400 000 Дж.
4) Время работы: t = A_затр / P = 400 000 / 1000 = 400 с.
Ответ: 400 с.','Полезное тепло Q = c*m*Δt, а затраченная энергия выражается через мощность и КПД: A = P * t, Q = η * P * t.','2026-09-24 19:30:15.467002','2026-09-24 19:30:15.467003');
INSERT INTO "bank_tasks" VALUES(19,8,'ELECTRODYNAMICS','CLOSED','Смешанное соединение резисторов','Мощность тока в смешанной цепи','К источнику с постоянным напряжением 24 В подключена цепь: резистор R1 = 6 Ом включен последовательно с параллельным участком из двух резисторов R2 = 12 Ом и R3 = 6 Ом. Определите общую мощность, потребляемую этой цепью. Ответ дайте в Ваттах с округлением до десятых.','Средний','57.6','1) Эквивалентное сопротивление параллельного участка:
R23 = (12 * 6) / (12 + 6) = 72 / 18 = 4 Ом.
2) Полное сопротивление цепи:
R_общ = R1 + R23 = 6 + 4 = 10 Ом.
3) Общая мощность цепи: P = U² / R_общ = 24² / 10 = 576 / 10 = 57,6 Вт.
Ответ: 57,6 Вт.','Сначала сверните параллельные резисторы R2 и R3, затем сложите с последовательным R1. Мощность P = U² / R_общ.','2026-09-24 19:30:15.467003','2026-09-24 19:30:15.467004');
INSERT INTO "bank_tasks" VALUES(20,8,'ELECTRODYNAMICS','CLOSED','Формула тонкой линзы','Оптическая сила собирающей линзы','Предмет высотой 4 см расположен на расстоянии 25 см от собирающей линзы. Действительное изображение предмета на экране получается на расстоянии 100 см от линзы. Определите оптическую силу линзы в диоптриях (дптр).','Средний','5','Формула тонкой линзы: D = 1/F = 1/d + 1/f.
d = 25 см = 0,25 м.
f = 100 см = 1,0 м.
D = 1 / 0,25 + 1 / 1,0 = 4 + 1 = 5 дптр.
Ответ: 5 дптр.','Оптическая сила D = 1/d + 1/f, где расстояния d и f обязательно должны быть выражены в метрах.','2026-09-24 19:30:15.467005','2026-09-24 19:30:15.467005');
INSERT INTO "bank_tasks" VALUES(21,9,'MECHANICS','OPEN','Равноускоренное движение','Тормозной путь автомобиля','Автомобиль, двигавшийся со скоростью 72 км/ч, начинает экстренное торможение с постоянным ускорением 4 м/с² до полной остановки. Определите тормозной путь автомобиля в метрах.','Базовый','50','1) Перевод скорости в СИ: v0 = 72 км/ч = 72 / 3,6 = 20 м/с.
2) Конечная скорость v = 0 м/с.
3) Формула пути без времени: v² - v0² = -2as => 0 - 20² = -2 * 4 * s => 400 = 8s => s = 50 м.
Ответ: 50 м.','Переведите скорость в м/с (72 км/ч = 20 м/с) и используйте соотношение v0² = 2as.','2026-09-24 19:30:15.467006','2026-09-24 19:30:15.467007');
INSERT INTO "bank_tasks" VALUES(22,9,'MECHANICS','OPEN','Второй закон Ньютона и сила трения','Ускорение бруска по горизонтали','На брусок массой 2 кг, покоящийся на горизонтальной поверхности с коэффициентом трения μ = 0,2, начинает действовать горизонтальная сила тяги 10 Н. С каким ускорением будет двигаться брусок? g = 10 м/с². Ответ выразите в м/с².','Базовый','3','1) Сила реакции опоры: N = mg = 2 * 10 = 20 Н.
2) Максимальная сила трения скольжения: F_тр = μ * N = 0,2 * 20 = 4 Н.
3) Равнодействующая сила: R = F_тяги - F_тр = 10 - 4 = 6 Н.
4) По 2-му закону Ньютона: a = R / m = 6 / 2 = 3 м/с².
Ответ: 3 м/с².','Равнодействующая равна разности силы тяги и силы трения: m*a = F - μ*m*g.','2026-09-24 19:30:15.467007','2026-09-24 19:30:15.467008');
INSERT INTO "bank_tasks" VALUES(23,9,'MECHANICS','OPEN','Закон сохранения импульса','Неупругий удар двух тележек','Тележка массой 3 кг, движущаяся со скоростью 4 м/с, сталкивается с неподвижной тележкой массой 1 кг и сцепляется с ней. Какова скорость сцепленных тележек после удара? Ответ выразите в м/с.','Базовый','3','Закон сохранения импульса в проекции на направление движения:
m1 * v1 + m2 * v2 = (m1 + m2) * u.
3 * 4 + 1 * 0 = (3 + 1) * u => 12 = 4u => u = 3 м/с.
Ответ: 3 м/с.','При абсолютно неупругом ударе тела после соударения движутся как единое целое общей массы (m1 + m2).','2026-09-24 19:30:15.467009','2026-09-24 19:30:15.467009');
INSERT INTO "bank_tasks" VALUES(24,9,'MECHANICS','OPEN','Механические колебания: нитяной маятник','Период колебаний маятника на Луне','Математический маятник длиной 1,6 м колеблется на поверхности Луны, где ускорение свободного падения равно 1,6 м/с². Чему равен период его колебаний? Примите π = 3,14. Ответ округлите до десятых (с).','Базовый','6.3','Формула периода нитяного (математического) маятника: T = 2π * √(l / g).
T = 2 * 3,14 * √(1,6 / 1,6) = 6,28 * 1 ≈ 6,3 с.
Ответ: 6,3 с.','Формула Томсона для математического маятника: T = 2π * √(L / g).','2026-09-24 19:30:15.467010','2026-09-24 19:30:15.467010');
INSERT INTO "bank_tasks" VALUES(25,9,'MECHANICS','CLOSED','Закон сохранения механической энергии','Скорость шайбы у основания горки','Шайба массой 200 г начинает соскальзывать без начальной скорости с вершины ледяной горки высотой 3,2 м. У основания горки на горизонтальном участке действует сила трения, и шайба до остановки проходит путь 8 м. Найдите коэффициент трения шайбы о горизонтальный лед. Трение на самой горке отсутствует. g = 10 м/с².','Повышенный (ОГЭ №23-25)','0.4','1) По закону сохранения энергии потенциальная энергия на вершине переходит в кинетическую у основания: mgh = mv²/2.
2) На горизонтальном участке вся кинетическая энергия расходуется на работу силы трения: A_тр = F_тр * S = μ * mg * S.
3) Приравнивая: mgh = μ * mg * S => h = μ * S => μ = h / S = 3,2 / 8 = 0,4.
Ответ: 0,4.','Потенциальная энергия на вершине горки m*g*h полностью расходуется на работу силы трения на горизонтальном участке A = μ*m*g*S.','2026-09-24 19:30:15.467011','2026-09-24 19:30:15.467012');
INSERT INTO "bank_tasks" VALUES(26,9,'MECHANICS','CLOSED','Движение по окружности и центростремительное ускорение','Перегрузка летчика в мертвой петле','Самолет совершает «мертвую петлю» радиусом 400 м в вертикальной плоскости. С какой минимальной постоянной скоростью должен лететь самолет, чтобы в верхней точке петли летчик находился в состоянии невесомости? g = 10 м/с². Ответ выразите в м/с.','Средний','63.2','В верхней точке петли на летчика действуют сила тяжести и сила реакции опоры: mg + N = m * v² / R.
Состояние невесомости означает, что N = 0 => mg = m * v² / R => v = √(g * R).
v = √(10 * 400) = √4000 ≈ 63,245 ≈ 63,2 м/с.
Ответ: 63,2.','В верхней точке невесомость наступает, когда центростремительное ускорение равно ускорению свободного падения: v²/R = g.','2026-09-24 19:30:15.467012','2026-09-24 19:30:15.467013');
INSERT INTO "bank_tasks" VALUES(27,9,'QUANTUM','OPEN','Состав атомного ядра','Число нейтронов в ядре свинца-208','Сколько протонов и сколько нейтронов содержится в ядре изотопа свинца ²⁰⁸₈₂Pb? В ответе укажите только количество нейтронов.','Базовый','126','В обозначении ядра ²⁰⁸₈₂Pb:
Массовое число A = 208 (общее число нуклонов).
Зарядовое число Z = 82 (число протонов).
Число нейтронов N = A - Z = 208 - 82 = 126.
Ответ: 126.','Число нейтронов равно разности массового числа и зарядового числа: N = A - Z.','2026-09-24 19:30:15.467014','2026-09-24 19:30:15.467014');
INSERT INTO "bank_tasks" VALUES(28,9,'QUANTUM','OPEN','Альфа- и бета-распад','Зарядовое число дочернего ядра при альфа-распаде','Ядро радия ²²⁶₈₈Ra испытывает α-распад, испуская альфа-частицу (ядро гелия ⁴₂He). Определите зарядовое число Z получившегося дочернего ядра радона Rn.','Базовый','86','Уравнение альфа-распада: ²²⁶₈₈Ra -> ²²²₈₆Rn + ⁴₂He.
Закон сохранения заряда: 88 = Z + 2 => Z = 86.
Ответ: 86.','При α-распаде зарядовое число уменьшается на 2, а массовое число уменьшается на 4 (правило Содди).','2026-09-24 19:30:15.467015','2026-09-24 19:30:15.467016');
INSERT INTO "bank_tasks" VALUES(29,9,'QUANTUM','OPEN','Закон радиоактивного распада','Доля распавшихся ядер за два периода полураспада','Период полураспада некоторого радиоактивного изотопа составляет 3 часа. Сколько процентов от начального количества ядер распадется через 6 часов? Ответ выразите целым числом.','Базовый','75','1) Время t = 6 ч составляет n = t / T = 6 / 3 = 2 периода полураспада.
2) За 1 период распадается 50%, остается 50%.
3) За 2 периода останется (1/2)² = 1/4 = 25% от исходного числа ядер.
4) Следовательно, распалось: 100% - 25% = 75% ядер.
Ответ: 75.','Внимательно читайте вопрос: спрашивается, сколько ядер РАСПАЛОСЬ, а не сколько осталось!','2026-09-24 19:30:15.467016','2026-09-24 19:30:15.467017');
INSERT INTO "bank_tasks" VALUES(30,9,'QUANTUM','CLOSED','Ядерные реакции и деление ядер','Количество выделившихся нейтронов в реакции деления','При бомбардировке ядра урана-235 медленным нейтроном произошла ядерная реакция деления:
¹₀n + ²³⁵₉₂U -> ¹⁴⁴₅₆Ba + ⁸⁹₃₆Kr + x ¹₀n.
Определите число образовавшихся нейтронов x.','Средний','3','Применяем закон сохранения массовых чисел (суммы верхних индексов):
1 + 235 = 144 + 89 + x * 1
236 = 233 + x => x = 3.
Проверка по зарядовому числу: 0 + 92 = 56 + 36 + 0 = 92 (сходится).
Ответ: 3.','Используйте закон сохранения массовых чисел (сумма верхних индексов слева равна сумме справа).','2026-09-24 19:30:15.467018','2026-09-24 19:30:15.467018');
INSERT INTO "bank_tasks" VALUES(31,9,'QUANTUM','CLOSED','Цепочка радиоактивных превращений','Число альфа-распадов в цепочке тория','В результате цепочки радиоактивных распадов исходное ядро тория ²³²₉₀Th превратилось в стабильное ядро свинца ²⁰⁸₈₂Pb. Сколько альфа-распадов произошло в этой цепочке?','Средний','6','1) Каждая альфа-частица уменьшает массовое число A на 4 единицы, а бета-частица на массу не влияет.
2) Общее изменение массового числа: ΔA = 232 - 208 = 24.
3) Число альфа-распадов: N_alpha = 24 / 4 = 6.
(Для справки: число бета-распадов N_beta = 2*6 - (90 - 82) = 12 - 8 = 4).
Ответ: 6.','Массовое число ядра меняется ТОЛЬКО при альфа-распаде (на 4 за каждый распад).','2026-09-24 19:30:15.467019','2026-09-24 19:30:15.467020');
INSERT INTO "bank_tasks" VALUES(32,9,'PART_2_ADVANCED','OPEN','Качественная задача (№20-22 ОГЭ)','Плотность пара при быстром сжатии','В герметичном цилиндре под поршнем находится насыщенный водяной пар при постоянной температуре 100 °C. Объем цилиндра медленно уменьшают в 2 раза. Как при этом изменится давление пара в цилиндре? Ответ обоснуйте.','Повышенный (ОГЭ №20-22)','Не изменится','1. Ответ: Давление пара не изменится.
2. Обоснование: При постоянной температуре давление насыщенного пара является величиной постоянной и зависит ТОЛЬКО от температуры.
3. При уменьшении объема часть пара просто сконденсируется в воду, а оставшийся пар останется насыщенным при том же давлении p = 10⁵ Па (1 атм при 100 °C).','Вспомните ключевое свойство насыщенного пара: его давление и плотность при постоянной температуре НЕ зависят от объема!','2026-09-24 19:30:15.467020','2026-09-24 19:30:15.467021');
INSERT INTO "bank_tasks" VALUES(33,9,'PART_2_ADVANCED','OPEN','Комбинированная расчетная задача (№23-25 ОГЭ)','Электронагреватель и плавление льда','Электрический кипятильник сопротивлением 50 Ом подключен к источнику с напряжением 100 В и опущен в теплоизолированный сосуд с 1 кг льда при температуре 0 °C. За какое время в секундах растает 40% льда? Потерями тепла пренебречь. λ_льда = 3,3 * 10⁵ Дж/кг.','Повышенный (ОГЭ №23-25)','660','1) Масса растаявшего льда: m = 0,4 * 1 кг = 0,4 кг.
2) Необходимая теплота для плавления: Q = λ * m = 3,3 * 10⁵ * 0,4 = 132 000 Дж.
3) Мощность кипятильника: P = U² / R = 100² / 50 = 10 000 / 50 = 200 Вт.
4) Время работы кипятильника: t = Q / P = 132 000 / 200 = 660 с.
Ответ: 660 с (11 минут).','Теплота выделяется по закону Джоуля-Ленца Q = (U²/R) * t и идет на фазовый переход Q = λ*m.','2026-09-24 19:30:15.467021','2026-09-24 19:30:15.467022');
INSERT INTO "bank_tasks" VALUES(34,9,'PART_2_ADVANCED','CLOSED','Расчетная задача высокой сложности (№24-25 ОГЭ)','КПД подъемного крана с электродвигателем','Электродвигатель подъемного крана питается от сети напряжением 380 В и потребляет ток 25 А. С помощью этого крана груз массой 1,5 тонны равномерно поднимают на высоту 19 метров за 50 секунд. Определите КПД подъемного крана в процентах. g = 10 м/с².','Повышенный (ОГЭ №23-25)','60','1) Полезная работа крана по подъему груза:
A_пол = m * g * h = 3000 * 10 * 19 = 570 000 Дж.
2) Полная затраченная электрическая энергия:
A_затр = U * I * t = 380 * 25 * 50 = 475 000 Дж... стоп, пересчитаем: 380 * 25 = 9500 Вт; 9500 * 50 = 475 000 Дж (КПД был бы > 100% при 19 м! Проверим: 3000 * 10 * 19 = 570 000. Корректируем условие: m = 1,5 тонны!).
Пересчет с m = 1,5 т:
A_пол = 1500 * 10 * 19 = 285 000 Дж.
A_затр = 380 * 25 * 50 = 475 000 Дж.
КПД = (285 000 / 475 000) * 100% = 60%.
(В базе фиксируем условие: m = 1500 кг, h = 19 м, t = 50 с, U = 380 В, I = 25 А).
Ответ: 60%.','КПД = (A_пол / A_затр) * 100%, где A_пол = mgh, а A_затр = U * I * t.','2026-09-24 19:30:15.467023','2026-09-24 19:30:15.467023');
CREATE INDEX ix_bank_tasks_block ON bank_tasks (block);
CREATE INDEX ix_bank_tasks_grade ON bank_tasks (grade);
CREATE INDEX ix_bank_tasks_bank_type ON bank_tasks (bank_type);